import {api,escape as e,requestId} from './workspace-shared.js';
import {blankReportingEntry,reportingEntry} from './reporting-model.mjs';
import {standardsLevels,gradeLabel} from './gradebook-model.mjs';

export function createReportingGradebook({root,classId,students=[],onConfigure=()=>{},onActivities=()=>{},onData=()=>{},initialCell=null}){
 const endpoint='/api/reporting/classes/'+classId+'/plans';let context,data,planId='',selected=null,editor=null,evidence=[],busy=false,closed=false,error='',notice='',query='',sort='name',dirty=false,review=false,chosen=new Set(),epoch=0;
 const $=s=>root.querySelector(s),key=(learnerId,code)=>learnerId+'|'+code;
 const plan=()=>data?.plan,targets=()=>plan()?.targets.filter(t=>t.report)||[],activity=code=>data?.activities.find(a=>a.reporting?.code===code),row=(learner,code)=>activity(code)?.entries.find(r=>r.learnerId===learner),suggestion=(learner,code)=>data?.suggestions.find(s=>s.learnerId===learner&&s.code===code&&s.baseAt===(row(learner,code)?.draft?.at||0));
 const label=(entry,t)=>!entry?'Not recorded':entry.state!=='observed'?'Insufficient evidence':plan().format==='standards'?standardsLevels[entry.judgments.find(j=>j.code===t.code)?.level||'unobserved']:String(entry.grade??'Not recorded')+(plan().format==='points'?' / '+plan().max:plan().format==='percentage'?'%':'');
 const canLeave=()=>{if(busy){notice='Wait for the current save or suggestion batch to finish.';render();return false;}if(dirty&&!confirm('Discard unsaved changes to this grade?'))return false;dirty=false;return true;};
 const draftRows=()=>targets().flatMap(t=>students.map(s=>({t,s,r:row(s.id,t.code)})).filter(({r})=>r?.draft&&r.draft.at!==r.published?.at));
 function render(){
  if(closed||!context)return;const active=document.activeElement,focusField=active?.closest('[data-rg-edit]'),focusKey=focusField?.dataset.rgEdit,selectionStart=focusField?.selectionStart,selectionEnd=focusField?.selectionEnd;const p=plan(),ts=targets(),people=students.filter(s=>!query||s.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):b.name.localeCompare(a.name)),drafts=draftRows(),suggestions=data?.suggestions.filter(s=>suggestion(s.learnerId,s.code)===s)||[];
  root.innerHTML=`<section class="reporting-shell"><div class="rp-toolbar"><label>Reporting unit<select data-rg-plan ${busy?'disabled':''}><option value="">Choose reporting unit…</option>${context.plans.map(p=>`<option value="${e(p.id)}" ${p.id===planId?'selected':''}>${e(p.title)}${p.period?' · '+e(p.period):''}</option>`).join('')}</select></label><div class="rp-actions"><button type="button" class="teacher-button secondary" data-rg-configure ${busy?'disabled':''}>${p?'Edit outcomes':'Choose reporting outcomes'}</button><button type="button" class="teacher-button secondary" data-rg-activities ${busy?'disabled':''}>Activity records</button><button type="button" class="teacher-button secondary" data-rg-refresh ${busy?'disabled':''}>Refresh</button></div></div><p role="alert" class="rp-error">${e(error)}</p><p role="status" data-rg-status>${e(notice)}</p>${p?`<div class="rp-toolbar"><div><h2>${e(p.period||'Unit reporting')}</h2><p>${ts.length} reporting outcomes · ${e(p.title)}</p></div><div class="rp-actions"><button type="button" class="teacher-button rp-ai" data-rg-suggest ${busy||!context.aiAvailable||!ts.length||!students.length?'disabled':''}>✦ Suggest grades</button><button type="button" class="teacher-button secondary" data-rg-accept-all ${busy||!suggestions.length?'disabled':''}>Accept all as drafts</button><button type="button" class="teacher-button" data-rg-review ${busy||!drafts.length?'disabled':''}>Review &amp; publish${drafts.length?' · '+drafts.length:''}</button></div></div><div class="rp-legend"><span>✦ AI suggestion</span><span>✎ Teacher draft</span><span>✓ Published</span><small>Accepting saves a private draft. Publication changes what families see.</small></div><div class="rp-toolbar"><label>Find a learner<input type="search" data-rg-search value="${e(query)}" placeholder="Student name"></label><label>Sort learners<select data-rg-sort><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="reverse" ${sort==='reverse'?'selected':''}>Name Z–A</option></select></label></div><div class="rp-gradebook-layout ${selected||review?'has-panel':''}"><div class="rp-table-scroll" tabindex="0" aria-label="Unit reporting Gradebook"><table class="rp-grade-table"><thead><tr><th scope="col">Student</th>${ts.map(t=>`<th scope="col"><strong>${e(t.label)}</strong><small>${e(t.code)}</small></th>`).join('')}</tr></thead><tbody>${people.map(s=>`<tr><th scope="row"><span class="rp-avatar" aria-hidden="true">${e(s.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}<img class="rp-portrait" src="/api/profiles/learners/${encodeURIComponent(s.id)}/image" alt="" loading="lazy"></span>${e(s.name)}</th>${ts.map(t=>{const r=row(s.id,t.code),ai=suggestion(s.id,t.code),draft=r?.draft&&r.draft.at!==r.published?.at,entry=r?.draft||r?.published||ai?.entry,state=draft?'draft':r?.published?'published':ai?'suggested':'none';return `<td><button type="button" class="rp-grade-cell" data-rg-cell="${e(s.id)}" data-code="${e(t.code)}" data-state="${state}" aria-label="${e(s.name+' · '+t.label+' · '+label(entry,t))}" aria-pressed="${selected?.learner===s.id&&selected?.code===t.code}"><span>${state==='suggested'?'✦':state==='draft'?'✎':state==='published'?'✓':''} ${e(label(entry,t))}</span><small>${state==='suggested'?'AI suggestion':state==='draft'?'Private draft':state==='published'?'Published':'Click to assess'}${ai&&r?.draft?' · Suggestion available':''}</small></button></td>`;}).join('')}</tr>`).join('')||`<tr><td colspan="${ts.length+1}">No learners match this view.</td></tr>`}</tbody></table></div>${review?reviewHTML():selected?panelHTML():''}</div><p class="rp-note">${suggestions.length} current suggestions · ${drafts.length} teacher drafts · ${data.activities.reduce((n,a)=>n+a.entries.filter(r=>r.published).length,0)} published. All reporting uses the unit’s selected scale.</p>`:'<div class="assessment-empty"><h3>Select the outcomes you will report on</h3><p>Choose unit standards in the planner. Teachers can still record scores, observations and feedback under Activity records.</p></div>'}</section>`;
  $('[data-rg-configure]').onclick=()=>{if(canLeave())onConfigure(planId);};$('[data-rg-activities]').onclick=()=>{if(canLeave())onActivities();};$('[data-rg-refresh]').onclick=()=>{if(canLeave())load();};
  $('[data-rg-plan]').onchange=ev=>{if(!canLeave()){ev.target.value=planId;return;}planId=ev.target.value;selected=null;dirty=false;review=false;choosePlan();};
  $('[data-rg-search]')?.addEventListener('input',ev=>{query=ev.target.value;const pos=ev.target.selectionStart;render();$('[data-rg-search]').focus();$('[data-rg-search]').setSelectionRange(pos,pos);});$('[data-rg-sort]')?.addEventListener('change',ev=>{sort=ev.target.value;render();});
  root.querySelectorAll('[data-rg-cell]').forEach(b=>b.onclick=()=>{if(canLeave())openCell(b.dataset.rgCell,b.dataset.code);});
  $('[data-rg-suggest]')?.addEventListener('click',()=>run(async()=>{for(let i=0;i<students.length;i+=5){notice=`Suggesting grades · students ${i+1}–${Math.min(i+5,students.length)} of ${students.length}…`;render();await api(endpoint+'/'+planId+'/suggestions',{planRevision:p.revision,learners:students.slice(i,i+5).map(s=>s.id),expectedUserId:context.userId,requestId:requestId()},{timeoutMs:155000});}await refreshData();notice='Suggestions are ready. Review each result or accept suggestions into empty draft cells.';}));
  $('[data-rg-accept-all]')?.addEventListener('click',()=>run(async()=>{let count=0,skipped=0;for(const s of suggestions){if(row(s.learnerId,s.code)?.draft||s.readiness!=='sufficient'){skipped++;continue;}await saveEntry(s.learnerId,s.code,s.entry,'draft',s.runId);count++;notice=`Accepted ${count} suggestion(s) as drafts…`;render();}notice=`${count} suggestions accepted as private drafts. ${skipped} existing teacher records or insufficient-evidence suggestions were left for individual review.`;}));
  $('[data-rg-review]')?.addEventListener('click',()=>{if(!canLeave())return;dirty=false;selected=null;review=true;chosen.clear();render();});
  $('[data-rg-close]')?.addEventListener('click',()=>{if(canLeave()){selected=null;review=false;dirty=false;render();}});
  root.querySelectorAll('[data-rg-edit]').forEach(f=>f.oninput=()=>{editor[f.dataset.rgEdit]=f.value;dirty=true;});
  $('[data-rg-level]')?.addEventListener('change',ev=>{editor.state=ev.target.value==='unobserved'?'unobserved':'observed';editor.judgments=[{code:selected.code,level:ev.target.value}];dirty=true;});
  $('[data-rg-number]')?.addEventListener('input',ev=>{editor.grade=ev.target.value===''?null:plan().format==='letter'?ev.target.value:Number(ev.target.value);editor.state=editor.grade===null?'unobserved':'observed';dirty=true;});
  $('[data-rg-use-ai]')?.addEventListener('click',()=>{const s=suggestion(selected.learner,selected.code);editor=structuredClone(s.entry);editor.runId=s.runId;dirty=true;render();});
  $('[data-rg-save]')?.addEventListener('click',()=>run(async()=>{await saveEntry(selected.learner,selected.code,editor,'draft',editor.runId);dirty=false;editor=structuredClone(row(selected.learner,selected.code).draft);notice='Teacher draft saved. Families still see the last published result.';}));
  root.querySelectorAll('[data-rg-publish-check]').forEach(f=>f.onchange=()=>{if(f.checked)chosen.add(f.dataset.rgPublishCheck);else chosen.delete(f.dataset.rgPublishCheck);$('[data-rg-publish]').disabled=!chosen.size;});
  $('[data-rg-select-all]')?.addEventListener('click',()=>{chosen=new Set(drafts.map(({s,t})=>key(s.id,t.code)));render();});
  $('[data-rg-publish]')?.addEventListener('click',()=>run(async()=>{let count=0;for(const {s,t,r} of drafts.filter(({s,t})=>chosen.has(key(s.id,t.code)))){await saveEntry(s.id,t.code,r.draft,'publish');count++;notice=`Published ${count} selected result(s)…`;render();}chosen.clear();notice=`${count} teacher-reviewed results published to students and linked parents.`;}));
  if(focusKey){const f=root.querySelector(`[data-rg-edit="${focusKey}"]`);f?.focus({preventScroll:true});if(f&&typeof selectionStart==='number')f.setSelectionRange(selectionStart,selectionEnd);}
  $('[data-rg-withdraw]')?.addEventListener('click',()=>run(async()=>{await saveEntry(selected.learner,selected.code,editor,'withdraw');dirty=false;notice='Published result withdrawn. The private teacher draft is retained.';}));
 }
 function panelHTML(){
  const t=targets().find(t=>t.code===selected.code),s=students.find(s=>s.id===selected.learner),r=row(s.id,t.code),ai=suggestion(s.id,t.code);
  return `<aside class="rp-review-panel" aria-label="Assessment review"><div class="rp-toolbar"><div><h3>${e(s.name)}</h3><p>${e(t.label)} · ${e(t.code)}</p></div><button type="button" class="text-button" data-rg-close aria-label="Close assessment review">×</button></div>${ai?`<div class="rp-ai-note"><strong>✦ AI suggestion · ${e(label(ai.entry,t))}</strong><p>${e(ai.entry.evidenceNote)}</p>${ai.limitations?`<p>${e(ai.limitations)}</p>`:''}<button type="button" class="teacher-button secondary" data-rg-use-ai ${busy?'disabled':''}>Use suggestion in draft</button></div>`:''}<fieldset ${busy?'disabled':''}><legend>Teacher judgment</legend>${plan().format==='standards'?`<label>Standards level<select data-rg-level>${Object.entries(standardsLevels).map(([k,v])=>`<option value="${k}" ${editor.judgments.find(j=>j.code===t.code)?.level===k||k==='unobserved'&&!editor.judgments.length?'selected':''}>${e(v)}</option>`).join('')}</select></label>`:plan().format==='letter'?`<label>Letter grade<select data-rg-number><option value="">Insufficient evidence</option>${plan().letters.map(l=>`<option ${editor.grade===l?'selected':''}>${e(l)}</option>`).join('')}</select></label>`:`<label>Teacher grade${plan().format==='points'?' / '+plan().max:' / 100'}<input data-rg-number type="number" min="0" max="${plan().format==='points'?plan().max:100}" step="any" value="${e(editor.grade??'')}"></label>`}<label>Evidence note<textarea data-rg-edit="evidenceNote" maxlength="2000" rows="3">${e(editor.evidenceNote)}</textarea></label><label>Feedback for student / parent<textarea data-rg-edit="feedback" maxlength="2000" rows="2">${e(editor.feedback)}</textarea></label><label>Next step<textarea data-rg-edit="nextStep" maxlength="1000" rows="2">${e(editor.nextStep)}</textarea></label><button type="button" class="teacher-button" data-rg-save>${editor.runId?'Accept as draft':'Save teacher draft'}</button></fieldset><details open><summary>Supporting evidence · ${evidence.filter(v=>v.codes.includes(t.code)).length}</summary>${evidence.filter(v=>v.codes.includes(t.code)).map(v=>`<details class="rp-evidence"><summary>${e(v.title)}<small>${e(v.kind)} · ${e(v.support||'Support unrecorded')} · ${e(typeof v.at==='number'?new Date(v.at).toLocaleDateString():v.at)}</small></summary><p>${e(v.text||'No readable student response.')}</p>${v.limitations?`<p class="rp-note">${e(v.limitations)}</p>`:''}${sourceLink(v,s.id)}</details>`).join('')||'<p class="rp-note">No aligned evidence loaded. Record an observation or link this student’s work in the unit planner.</p>'}</details><details><summary>Reporting criteria</summary><p>${e(t.description)}</p>${Object.entries(t.rubric).filter(([,v])=>v).map(([k,v])=>`<p><strong>${e(standardsLevels[k])}:</strong> ${e(v)}</p>`).join('')}</details><div class="rp-last-published"><strong>Last published</strong><p>${r?.published?e(label(r.published,t))+' · '+e(new Date(r.published.at).toLocaleDateString()):'No published result'}</p><p class="rp-note">Families continue to see this result until you publish an update.</p>${r?.published?'<button type="button" class="text-button" data-rg-withdraw>Withdraw published result</button>':''}</div>${r?.draft?.sourceEvidence?.type==='ai-suggestion'?'<p class="rp-note">This draft was reviewed from an AI suggestion. Its original proposal and evidence snapshot are retained in assessment history.</p>':''}</aside>`;
 }
 function sourceLink(v,learnerId){if(v.kind==='notebook')return `<a target="_blank" rel="noopener" href="/notebooks?${new URLSearchParams({classId,notebookId:classId+'.'+learnerId,pageId:v.sourceId})}">Open notebook page ↗</a>`;if(v.kind==='teacher')return '<span class="rp-note">Recorded teacher evidence</span>';return '';}
 function reviewHTML(){const drafts=draftRows();return `<aside class="rp-review-panel" aria-label="Review publication"><div class="rp-toolbar"><h3>Review &amp; publish</h3><button type="button" class="text-button" data-rg-close aria-label="Close publication review">×</button></div><p>Only checked teacher drafts will become visible to students and their linked parents.</p><button type="button" class="text-button" data-rg-select-all ${busy?'disabled':''}>Select all ${drafts.length} drafts</button>${drafts.map(({s,t,r})=>`<label class="rp-publish-row"><input type="checkbox" data-rg-publish-check="${e(key(s.id,t.code))}" ${chosen.has(key(s.id,t.code))?'checked':''} ${busy?'disabled':''}><span><strong>${e(s.name)}</strong><small>${e(t.label)} · ${e(label(r.draft,t))}</small>${r.draft.feedback?`<small>${e(r.draft.feedback)}</small>`:''}</span></label>`).join('')||'<p>No unpublished teacher drafts remain.</p>'}<button type="button" class="teacher-button" data-rg-publish ${busy||!chosen.size?'disabled':''}>Publish selected</button></aside>`;}
 async function openCell(learner,code){selected={learner,code};review=false;dirty=false;const r=row(learner,code),ai=suggestion(learner,code);editor=structuredClone(r?.draft||r?.published||ai?.entry||blankReportingEntry());if(!r?.draft&&ai)editor.runId=ai.runId;evidence=[];render();const token=++epoch;try{const result=await api(endpoint+'/'+planId+'/evidence?learner='+encodeURIComponent(learner));if(token!==epoch||closed)return;evidence=result.evidence;render();}catch(err){if(token===epoch){error=err.message;render();}}}
 async function saveEntry(learnerId,code,entry,mode,runId){const expectedAt=row(learnerId,code)?.draft?.at||0,result=await api(endpoint+'/'+planId+'/entries',{planRevision:plan().revision,learnerId,code,expectedAt,mode,entry:reportingEntry(entry,plan(),targets().find(t=>t.code===code)),...(runId?{runId}:{}),requestId:requestId(),expectedUserId:context.userId});data.activities=data.activities.filter(a=>a.id!==result.activity.id);data.activities.push(result.activity);onData(result.activity);}
 async function run(fn){if(busy)return;busy=true;error='';render();try{await fn();}catch(err){notice='';error=err.message+' Any earlier successful saves in this batch have been retained.';if(planId)try{await refreshData();}catch{}}finally{busy=false;if(!closed)render();}}
 async function refreshData(){const result=await api(endpoint+'/'+planId);if(!closed)data=result;}
 async function choosePlan(){selected=null;review=false;dirty=false;data=null;const url=new URL(location.href);if(planId)url.searchParams.set('reportingPlan',planId);else url.searchParams.delete('reportingPlan');history.replaceState(null,'',url);if(planId){notice='Loading reporting unit…';render();try{await refreshData();notice='';if(initialCell&&targets().some(t=>t.code===initialCell.code)&&students.some(s=>s.id===initialCell.learner)){const cell=initialCell;initialCell=null;await openCell(cell.learner,cell.code);}}catch(err){error=err.message;}}render();}
 async function load(){try{error='';notice='Loading Gradebook…';context=await api(endpoint);if(closed)return;const wanted=new URLSearchParams(location.search).get('reportingPlan');planId=context.plans.some(p=>p.id===(planId||wanted))?(planId||wanted):context.plans[0]?.id||'';await choosePlan();}catch(err){if(!closed)root.innerHTML=`<p role="alert">${e(err.message)}</p>`;}}
 const imageError=event=>{if(event.target.matches('.rp-portrait'))event.target.hidden=true;};root.addEventListener('error',imageError,true);root.innerHTML='<p role="status">Loading Gradebook…</p>';load();
 return {canLeave,hasChanges:()=>dirty||busy,clear(){closed=true;epoch++;root.removeEventListener('error',imageError,true);root.replaceChildren();}};
}
